import json,subprocess,tempfile,pathlib
runs=json.load(open('media-status.json'))['runs']
with tempfile.TemporaryDirectory(dir='.') as d:
 for n,r in enumerate(runs,1):
  result=subprocess.run(['sips','-s','format','tiff',r['images'][0]['file_path'],'--out',str(pathlib.Path(d)/f'{n}.tiff')],capture_output=True,text=True)
  if result.returncode or not (pathlib.Path(d)/f'{n}.tiff').is_file(): raise RuntimeError(f'{n}: {result.stderr}')
  print(f'{n}: PNG decoded successfully')
PY","timeoutMs":120000}

